$checks=[];function pagination_check($ok,$label,$details=null){global$checks;$checks[]=['ok'=>(bool)$ok,'check'=>$label,'details'=>$ok?null:$details];}
$db=new GTLM_Analytics_DB();global$wpdb;GTLM_Analytics::delete();GTLM_Analytics::enable();$gen=GTLM_Analytics::config()['generation'];
$cat=$db->insert_category(['name'=>'Pagination fixture','slug'=>'pagination-fixture']);$id=$db->insert_link(['name'=>'Many referrers','slug'=>'many-referrers','url'=>home_url('/target'),'category_id'=>$cat]);$other=$db->insert_link(['name'=>'Other referrers','slug'=>'other-referrers','url'=>home_url('/target')]);
function page_event($id,$page){global$db,$gen;$db->append(['link_id'=>$id,'occurred_at'=>gmdate('Y-m-d H:i:s'),'generation'=>$gen,'source'=>'pages.example.org','page'=>$page,'country'=>'IN','device'=>'desktop','browser'=>'chrome','os'=>'linux','campaign'=>0,'status'=>302,'mode'=>'standard','geo'=>'off']);}
