// A historical total has no page dimension: merge it into the same unavailable entry once.
$bucket=gmdate('Y-m-d H:i:00');$wpdb->query($wpdb->prepare('INSERT INTO '.GTLM_Analytics_DB::hourly_table()." (link_id,bucket_start,dimension,value,clicks) VALUES(%d,%s,'total','',4) ON DUPLICATE KEY UPDATE clicks=clicks+4",$id,$bucket));
