for($n=1;$n<=3;$n++){$r=GTLM_Analytics_Controller::pages(['link_id'=>$id,'sources_page'=>$n]);if(!$first)$first=$r;$seen=array_merge($seen,array_column($r['rows'],'value'));$sum+=array_sum(array_column($r['rows'],'clicks'));pagination_check(count($r['rows'])===($n===3?16:20),'Every result page has the expected bounded rows '.$n,$r);}
pagination_check(count($seen)===56&&count(array_unique($seen))===56&&$sum===62,'All retained entries are reachable once and their counts reconcile');pagination_check($first['pagination']['total_items']===56&&$first['pagination']['total_pages']===3,'Pagination reports the full result count');pagination_check($first['rows'][0]===['value'=>'','clicks'=>'7'],'Unknown and pre-attribution history form one entry');
$r=GTLM_Analytics_Controller::pages(['category_id'=>$cat,'sources_page'=>2]);pagination_check($r['pagination']['total_items']===56&&!in_array('https://pages.example.org/other/',array_column($r['rows'],'value'),true),'Category filtering applies to count and page rows');
$r=GTLM_Analytics_Controller::report(['link_id'=>$id,'sources_page'=>3]);pagination_check(count($r['pages'])===16&&$r['pages_pagination']['total_items']===56,'Summary API exposes all result pages and metadata');
$r=GTLM_Analytics_Controller::pages(['link_id'=>$id,'sources_page'=>999999999]);pagination_check($r['pagination']['current_page']===3&&!$r['pagination']['has_next'],'Out-of-range requests clamp before computing an offset');
