$r=GTLM_Analytics_Controller::pages(['link_id'=>999999]);pagination_check($r['rows']===[]&&$r['pagination']['total_items']===0&&$r['pagination']['from']===0,'Empty selections have accurate pagination');
foreach([10,50,100] as $size){$entries=[];$first_page=GTLM_Analytics_Controller::pages(['link_id'=>$id,'sources_per_page'=>$size]);for($n=1;$n<=$first_page['pagination']['total_pages'];$n++){$part=GTLM_Analytics_Controller::pages(['link_id'=>$id,'sources_per_page'=>$size,'sources_page'=>$n]);$entries=array_merge($entries,$part['rows']);}pagination_check(count($first_page['rows'])===min(56,$size)&&$first_page['pagination']['per_page']===$size&&count($entries)===56&&count(array_unique(array_column($entries,'value')))===56&&array_sum(array_column($entries,'clicks'))===62,'Chosen row count preserves the complete report: '.$size);}
$invalid_sizes=[0,-1,1,200,'20.5','bad',[],true];$sizes_rejected=true;foreach($invalid_sizes as $size){$sizes_rejected=$sizes_rejected&&is_wp_error(GTLM_Analytics_Controller::filters(['sources_per_page'=>$size]));}pagination_check($sizes_rejected,'Unsupported row counts are rejected');
wp_set_current_user(1);$_GET=['view'=>'pages','link_id'=>(string)$id,'sources_page'=>'2'];ob_start();GTLM_Analytics_View::render();$html=ob_get_clean();pagination_check(str_contains($html,'Showing 21–40 of 56')&&str_contains($html,'sources_page=3')&&str_contains($html,'name="view" value="pages"')&&!str_contains($html,'gtlm-analytics-chart'),'Dedicated listing includes pagination and preserves its view');
$_GET=['view'=>'pages','link_id'=>(string)$id,'sources_page'=>'2','sources_per_page'=>'10'];ob_start();GTLM_Analytics_View::render();$html=ob_get_clean();preg_match('/<form method="get" class="gtlm-pages-size">(.*?)<\/form>/s',$html,$size_form);pagination_check(str_contains($html,'Showing 11–20 of 56')&&str_contains($html,'sources_per_page=10')&&str_contains($html,'name="sources_per_page" value="10"')&&!str_contains($size_form[1]??'','name="sources_page"'),'Page size survives navigation and filter forms; resizing resets the result page');
$_GET=['view'=>'overview','link_id'=>(string)$id];ob_start();GTLM_Analytics_View::render();$html=ob_get_clean();pagination_check(!str_contains($html,'id="gtlm-referring-pages"')&&str_contains($html,'view=pages'),'Overview links to the separate page rather than embedding a truncated table');
$_GET=['page'=>'gtlm-links-settings'];$s=GTLM_Settings::get_instance();$view=new GTLM_Admin_Pages($db,$s,new GTLM_Import($db,$s));ob_start();$view->render_settings_page();$html=ob_get_clean();preg_match('/<textarea id="gtlm-ai-prompt"[^>]*>(.*?)<\/textarea>/s',$html,$matches);$prompt=html_entity_decode($matches[1]??'');pagination_check(str_contains($prompt,home_url('/'))&&str_contains($prompt,'https://gauravtiwari.org/gt-link-manager-rest-api-guide-ai-tools/')&&str_contains($prompt,'Ask only for missing information')&&str_contains($prompt,'read-only requests'),'Setup prompt includes this site, the guide and missing-detail instructions');pagination_check(str_contains($html,'id="gtlm-copy-ai-prompt"')&&str_contains($html,'role="status"'),'Copy prompt has a labelled action and accessible feedback');
$db->delete_link($id);$db->delete_link($other);$wpdb->delete(GTLM_DB::categories_table(),['id'=>$cat],['%d']);GTLM_Analytics::delete();$out=['passed'=>count(array_filter($checks,fn($c)=>$c['ok'])),'checks'=>$checks,'failed'=>array_values(array_filter($checks,fn($c)=>!$c['ok']))];echo json_encode($out,JSON_PRETTY_PRINT);exit($out['failed']?1:0);
